    },
    "blendingMode": {
      "type": "string",
      "description": "Blending mode: Override | Additive (default Override).",
      "default": "Override"
    },
    "dry_run": {
      "type": "boolean",
      "description": "If true, validate inputs without writing the layer.",
      "default": false
    }
  },
  "required": [
    "controller",
    "name"
  ],
  "additionalProperties": false,
  "x-command-metadata": {
    "mainThreadRequired": true,
    "methodName": "Unity.Pipeline.Editor.Commands.Animation.AnimatorControllerCommands.AddAnimatorLayer"
  }
}

