{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "title": "add_animator_state",
  "description": "Add a state to a layer, optionally with a motion (AnimationClip or BlendTree) and as the layer default. A layer name with no match returns code 'layer_not_found'.",
  "properties": {
    "controller": {
      "type": "string",
      "description": "Reference to the AnimatorController to edit (path / guid / globalId)."
    },
    "layer": {
      "type": "string",
      "description": "Layer index (int) or name (string). Default 0 (Base Layer)."
    },
    "name": {
      "type": "string",
      "description": "State name."
    },
    "motion": {
      "type": "string",
      "description": "Optional AnimationClip or BlendTree asset to assign as the state's motion."
    },
    "isDefault": {
      "type": "boolean",
      "description": "If true, set this state as the layer's default state.",
      "default": false
    },
    "position": {
      "type": "string",
      "description": "Optional [x, y] node position in the graph (cosmetic)."
    },
    "dry_run": {
      "type": "boolean",
      "description": "If true, validate inputs without writing the state.",
      "default": false
    }
  },
  "required": [
    "controller",
    "name"
  ],
  "additionalProperties": false,
  "x-command-metadata": {
    "mainThreadRequired": true,
    "methodName": "Unity.Pipeline.Editor.Commands.Animation.AnimatorControllerCommands.AddAnimatorState"
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "title": "add_animator_transition",
  "description": "Add a transition between two states (or from AnyState/Entry, to Exit) on a layer, with optional conditions. Validates that the states exist and each condition's parameter exists and its mode matches the parameter type.",
  "properties": {
    "controller": {
      "type": "string",
      "description": "Reference to the AnimatorController to edit (path / guid / globalId)."
    },
    "layer": {
      "type": "string",
      "description": "Layer index (int) or name (string). Default 0 (Base Layer)."
    },
    "fromState": {
      "type": "string",
      "description": "Source state name, or the special \"AnyState\" / \"Entry\"."
    },
    "toState": {
      "type": "string",
      "description": "Destination state name, or the special \"Exit\"."
    },
    "conditions": {
      "type": "string",
      "description": "Optional conditions: [{ parameter, mode: \"If\"|\"IfNot\"|\"Greater\"|\"Less\"|\"Equals\"|\"NotEqual\", threshold? }]."
    },
    "hasExitTime": {
      "type": "boolean",
      "description": "If true, the transition uses exit time (default false).",
      "default": false
    },
    "exitTime": {
      "type": "number",
      "description": "Normalized exit time (0..1) when hasExitTime is set.",
      "default": 0.0
    },
    "duration": {
      "type": "number",
      "description": "Transition duration in seconds (default 0.25).",
      "default": 0.25
    },
    "hasFixedDuration": {
      "type": "boolean",
      "description": "If true, duration is in seconds; otherwise normalized (default true).",
      "default": true
    },
    "dry_run": {
      "type": "boolean",
      "description": "If true, validate everything (states, parameters, mode/type) without writing the transition.",
      "default": false
    }
  },
  "required": [
    "controller",
    "fromState",
    "toState"
  ],
  "additionalProperties": false,
  "x-command-metadata": {
    "mainThreadRequired": true,
    "methodName": "Unity.Pipeline.Editor.Commands.Animation.AnimatorControllerCommands.AddAnimatorTransition"
  }
}

