{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "title": "batch",
  "description": "Run multiple registered commands in one transactional request. Later ops can reference earlier results with \"$<id-or-index>.<jsonPath>\" (e.g. \"$0.instanceId\"; \"$$\" escapes a literal '$'). transactional=true (default) groups every op into one Undo step and reverts all applied ops if any op fails; commands that mutate outside the Undo system (asset/file/settings writes) are rejected unless transactional=false. on_error=abort|continue (continue forces transactional=false); dry_run validates without mutating; time_budget_ms (default 50000) bounds execution — when exceeded the remaining ops are skipped and a transactional batch rolls back (submit long batches with \"job\": true). Excludes build, switch_build_target, package_*, editor_play/stop/pause, recompile, eval, eval_file, run_script, menu, open_scene/create_scene, async commands (run_tests/list_tests), runtime-only commands, and nested batch.",
  "properties": {
    "operations": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Optional id for referencing this op's result from a later op (\"$<id>.<field>\"). Unique within the batch; must match ^[A-Za-z_][A-Za-z0-9_-]*$ (not purely numeric, no dots)."
          },
          "command": {
            "type": "string",
            "description": "Name of the registered command to run."
          },
          "params": {
            "type": "string",
            "description": "Parameters for the command. String values may reference a prior op's result: \"$<id-or-index>.<jsonPath>\"."
          }
        },
        "required": [
          "command"
        ],
        "additionalProperties": false
      },
      "description": "Ordered operations to run; each is { id?, command, params }. Max 200."
    },
    "transactional": {
      "type": "boolean",
      "description": "Group all ops into one Undo step and revert every applied op if any op fails. Default true. Forced false when on_error=continue. Rejects commands whose mutations Undo cannot revert (asset/file/settings writes).",
      "default": true
    },
    "on_error": {
      "type": "string",
      "description": "abort (default): stop at the first failing op. continue: run every op, collecting per-op errors (forces transactional=false).",
      "default": "abort"
    },
    "dry_run": {
      "type": "boolean",
      "description": "Validate command names, parameters, reference topology and excluded commands without mutating anything.",
      "default": false
    },
    "result_fields": {
      "type": "string",
      "description": "Optional per-op result projection: map of op id-or-index -> array of result field paths to keep (context economy)."
    },
    "time_budget_ms": {
      "type": "integer",
      "description": "Cooperative time budget for the whole batch in milliseconds (default 50000, max 3600000). Checked before each op after the first; when exhausted the remaining ops are skipped and a transactional batch rolls back. Use \"job\": true for long batches.",
      "default": 50000
    }
  },
  "required": [
    "operations"
  ],
  "additionalProperties": false,
  "x-command-metadata": {
    "mainThreadRequired": true,
    "methodName": "Unity.Pipeline.Editor.Commands.Batch.BatchCommand.Batch"
  }
}

