    "confirm": {
      "type": "boolean",
      "description": "Acknowledge and run the build; without it the call is refused. Use dry_run to validate only.",
      "default": false
    },
    "dry_run": {
      "type": "boolean",
      "description": "Validate target/outputPath/scenes without building.",
      "default": false
    }
  },
  "required": [],
  "additionalProperties": false,
  "x-command-metadata": {
    "mainThreadRequired": false,
    "methodName": "Unity.Pipeline.Editor.Commands.Build.BuildCommand.Build"
  }
}

